import numpy as np

def heuristic(dist_m, turn_deg, swath_len_m, energy_left_frac, depot_dist_m, fits):
    # Hard feasibility gate: Infinite penalty for infeasible moves (_multiplication suppresses others)
    return np.where(fits > 0, 
        (1.0 - (1.0 - fits) * 20.0) *  # Energy feasibility (smoothed 0 to 1 near cutoff)
        * np.cos(np.radians(turn_deg - 180.0) / 2.0) *  # Turn continuity (180=best, 0=worst)
        * (1.0 + (1.0 - energy_left_frac) * 50.0 / (depot_dist_m + 1.0))   # Dynamic depot bias
